#include <stdio.h>
int main(void) {
    float grams = 0.0f;
    if (scanf("%f", &grams) != 1) return 1;
    double cost = grams * 16.0;
    printf("cost=%.2f\n", cost);
    return 0;
}

#include <stdio.h>
int main(void) {
    int saved = 12;
    printf("stored=%d constant=%d\n", saved, 40);
    return 0;
}

#include <stdio.h>
int main(void) {
    unsigned int code = 26u;
    printf("decimal=%u octal=%o hex=%x upper=%X\n", code, code, code, code);
    return 0;
}

#include <stdio.h>
int main(void) {
    short small = 120;
    long capacity = 70000L;
    unsigned long mask = 31UL;
    printf("small=%hd capacity=%ld mask=%lu\n", small, capacity, mask);
    return 0;
}

#include <stdio.h>
int main(void) {
    char letter = 0;
    if (scanf("%c", &letter) != 1) return 1;
    printf("character=%c code=%d\n", letter, letter);
    return 0;
}

#include <stdio.h>
#include <stdint.h>
#include <inttypes.h>
int main(void) {
    int_least32_t records = 200000;
    printf("records=%" PRIdLEAST32 "\n", records);
    return 0;
}

#include <stdio.h>
int main(void) {
    float ratio = 3.25f;
    printf("fixed=%f scientific=%e\n", ratio, ratio);
    return 0;
}

#include <stdio.h>
int main(void) {
    printf("short=%zu long=%zu long_double=%zu pointer=%zu\n",
           sizeof(short), sizeof(long), sizeof(long double), sizeof(int *));
    return 0;
}

#include <stdio.h>
int main(void) {
    int boxes = 4;
    printf("boxes=%d rows=%d\n", boxes);
    return 0;
}

