#include <stdio.h>
int main(void) {
    int raw = getchar();
    if (raw != EOF) {
        char stored = (char)raw;
        int promoted = stored;
        printf("%d\n", promoted);
    } else {
        printf("%d\n", -1);
    }
    return 0;
}

