#include <stdio.h>
int main(void) {
    double incoming = 0.0;
    if (scanf("%lf", &incoming) != 1) return 1;
    float narrowed = (float)incoming;
    double widened = narrowed;
    double scaled = widened + widened + widened;
    scaled = scaled * 2.0 + 0.25;
    printf("%.2f\n", scaled);
    return 0;
}

