exercises.referenceSource:
#include <stdio.h>
int main(void) {
    int choice = 0;
    if (scanf("%d", &choice) != 1) return 1;
    unsigned int bytes = 0u;
    switch (choice) {
        case 0: bytes = sizeof(char); break;
        case 1: bytes = sizeof(int); break;
        case 2: bytes = sizeof(double); break;
        case 3: bytes = sizeof(int *); break;
        default: return 1;
    }
    printf("%u\n", bytes);
    return 0;
}
